import java.io.*;
import java.util.*;
import java.math.BigInteger;

public class Main {
    static final BigInteger MOD = BigInteger.valueOf(998244353);
    static long[] fac;
    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        int t = 1;
        while (t-- > 0) {
            int n = sc.nextInt();
            long kk = sc.nextLong();
            fac = new long[n + 1];
            fac[0] = 1L;
            for (int i = 1; i <= n; i++) fac[i] = (fac[i - 1] * i) % MOD.longValue();
            if (kk == 0) {
                out.println(fac[n]);
            } else if (kk >= n) {
                out.println(0);
            } else {
                int k = (int) kk;
                BigInteger tmp = BigInteger.ZERO;
                int sign = 1;
                int l = n - k;
                for (int i = 0; i <= l; i++) {
                    BigInteger term = BigInteger.valueOf(powMod(l - i, n))
                        .multiply(BigInteger.valueOf(comb(l, l - i)))
                        .mod(MOD);
                    if (sign == -1) term = term.negate();
                    tmp = tmp.add(term).mod(MOD);
                    sign = -sign;
                }
                BigInteger res = BigInteger.valueOf(2)
                    .multiply(BigInteger.valueOf(comb(n, k)))
                    .multiply(tmp)
                    .mod(MOD);
                out.println(res.longValue());
            }
        }
        out.close();
    }
    static long comb(int n, int m) {
        if (m == 0 || m == n) return 1L;
        if (m > n || m < 0) return 0L;
        return fac[n] * powMod((fac[m] * fac[n - m]) % MOD.longValue(), MOD.longValue() - 2) % MOD.longValue();
    }
    static long powMod(long base, long exp) {
        long ans = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) ans = (ans * base) % MOD.longValue();
            base = (base * base) % MOD.longValue();
            exp >>= 1;
        }
        return ans;
    }
    static class MyScanner {
        BufferedReader br;
        StringTokenizer st;
        MyScanner() { br = new BufferedReader(new InputStreamReader(System.in)); }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try { st = new StringTokenizer(br.readLine()); }
                catch (IOException e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() {
            String str = "";
            try { str = br.readLine(); } catch (IOException e) { e.printStackTrace(); }
            return str;
        }
    }
}
